#!/usr/bin/env node
/**
 * `codereach` entry point.
 *
 * A thin shim so that `npx @cultivx/codereach` works from a published tarball
 * without any setup: it runs the bundled CLI produced by `pnpm build`, and
 * falls back to the TypeScript source via Node's type-stripping so a fresh
 * checkout in the monorepo is runnable before anything has been compiled.
 */
import { existsSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { pathToFileURL, fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))

const bundled = join(here, '..', 'dist', 'main.mjs')
const source = join(here, '..', 'src', 'main.ts')

if (existsSync(bundled)) {
  await import(pathToFileURL(bundled).href)
} else if (here.includes('node_modules')) {
  // An installed copy with no bundle is a broken install. The source
  // fallback cannot help here: Node refuses to strip types from files under
  // node_modules, and the error it throws says nothing about what is wrong.
  // Say what is wrong instead.
  process.stderr.write(
    'This copy of the CodeReach CLI is incomplete: the bundle (dist/main.mjs) is missing.\n' +
      'Reinstall it: npm install -g @cultivx/codereach\n',
  )
  process.exit(1)
} else {
  // Node >= 22 can execute TypeScript directly. Setting the flag for the
  // current process is not possible after start, so this path is only a
  // developer convenience; the published package always has `dist`.
  const { spawnSync } = await import('node:child_process')
  const result = spawnSync(process.execPath, ['--experimental-strip-types', source, ...process.argv.slice(2)], {
    stdio: 'inherit',
  })
  process.exit(result.status ?? 1)
}

