/**
 * `codereach`: turn a local OpenCode session into something your phone can
 * drive.
 *
 * The whole product is this file's startup sequence: get a loopback OpenCode
 * running, ask the relay for a pairing, print a QR, and then shuttle frames
 * until Ctrl+C. Everything else is plumbing underneath it.
 */

export interface CliOptions {
  name?: string
  model?: string
  relay?: string
  attach?: string
  yes?: boolean
  /** Skip typing the pairing code. Separate from `--yes`, which is the first-run consent only. */
  e2eAutoAccept?: boolean
  /** `--no-e2e` sets this to false. Absent or true means end to end. */
  e2e?: boolean
  verbose?: boolean
  logLevel?: LogLevel
}

const APP_NAME = 'CodeReach'

/**
 * Set to `1` to print the end-to-end pairing QR and link even when stdout is not a terminal, and so
 * to allow `--e2e-auto-accept` there. Whoever can read that output can then pair, with no code.
 */
export const SHOW_PAIRING_PIPE_ENV = 'CODEREACH_E2E_SHOW_PAIRING_IN_PIPE'

/** Whether the end-to-end pairing QR and link may be printed: to a terminal, or where the owner opted in. */
export function pairingShown(stdoutIsTty: boolean | undefined, env: NodeJS.ProcessEnv): boolean {
  return stdoutIsTty === true || env[SHOW_PAIRING_PIPE_ENV] === '1'
}

/** OpenCode events after which a session's status may have changed. */
const STATUS_EVENT = /^(session\.(execution|permission|permissions|created|deleted|renamed|metadata|idle|error|inbox)|permission\.|form\.|question\.)/

/** Prefix every line with two spaces, so a pasted block stays visibly a block. */
function indent(text: string): string {
  return text
    .replace(/\s+$/, '')
    .split('\n')
    .map((line) => `  ${line}`)
    .join('\n')
}

/** The last `count` lines of a log. */
function tail(text: string, count: number): string {
  const lines = text.replace(/\s+$/, '').split('\n')
  return lines.slice(Math.max(0, lines.length - count)).join('\n')
}

/**
 * The absolute path of a program on this shell's PATH.
 *
 * The service needs it once, at install time: launchd and systemd do not
 * inherit a login shell's PATH, so the unit has to name the directory.
 */
function findOnPath(name: string): string | null {
  try {
    const found = execFileSync('which', [name], { encoding: 'utf8', timeout: 2000 }).trim()
    return found.length > 0 ? found : null
  } catch {
    return null
  }
}

function messageOf(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

