      'label for this session in the app (default: this machine\'s hostname)',
    )
    .option(
      '-m, --model <provider/model>',
      'model for sessions created from the phone, e.g. opencode/deepseek-v4.1-flash-free',
    )
    .option('-r, --relay <url>', `the CodeReach relay to use, not OpenCode (default: ${DEFAULT_RELAY_URL})`)
