  const language = () =>
    new Option(
      '-l, --language <language>',
      'which language you speak to your agent: en, multi, or auto (default: auto)',
    ).choices(['en', 'multi', 'auto'])

  voice
    .command('status')
    .description('what is installed, and which pack is selected')
    .action(() => onVoice({ action: 'status' }))

  voice
    .command('setup')
    .description('choose and download a voice model')
    .addOption(language())
    .option('--force', 'download again, even if a model is already installed')
    .action((options: { language?: 'en' | 'multi' | 'auto'; force?: boolean }) =>
      onVoice({
        action: 'setup',
        language: options.language,
        ...(options.force ? { force: true } : {}),
      }),
    )

  voice
    .command('remove')
    .description('delete a voice model from this computer')
    .addOption(language())
    .option('--all', 'remove every installed voice model')
    .action((options: { language?: 'en' | 'multi' | 'auto'; all?: boolean }) =>
      onVoice({ action: 'remove', language: options.language, all: options.all }),
    )

  return program
}

/**
 * `codereach service ...`: the background service.
 *
 * Installing asks for nothing interactive: the folder is the one you ran it
 * from, the pairing is the one this computer already has (or the note the
 * service leaves), and everything it writes is under `~/.codereach`.
 */
export async function runService(
  command: ServiceCommand,
  io: Io,
  settings: { relayUrl?: string } = {},
): Promise<number> {
  const env = io.env ?? process.env
  const home = homeDir(env)
  const platform = process.platform
  const options = {
    home,
    projectDir: process.cwd(),
    // The install is a terminal command with its own output; the JSON logger is for
    // the service's log file, not for interrupting the banner.
    logger: createLogger('warn', { component: 'service' }),
    sourceRoot: packageRootFrom(process.argv[1]),
    version: AGENT_VERSION,
    opencodePath: findOnPath('opencode'),
    ...(settings.relayUrl ? { relayUrl: settings.relayUrl } : {}),
    env,
  }

  try {
    if (!serviceSupported(platform)) {
      io.stderr('\n  A background service is only supported on macOS and Linux.\n')
      return 1
    }

    if (command.action === 'install') {
      // An npx copy lives in npm's cache, which may be cleaned at any time. A
      // unit pointing there would fail on the next boot with nothing to see.
      const method = detectInstallMethod({ argvPath: process.argv[1], execPath: process.execPath, env })
      if (method === 'npx') {
        io.stderr(
          '\n  This copy is running from npx, which is not a stable place to start a service from.\n' +
            '  Install it first, then run the service command again:\n\n' +
            '    npm install -g @cultivx/codereach\n' +
            '    codereach service install\n',
        )
        return 1
      }

      io.stdout('\n  Installing the CodeReach service.\n')
      io.stdout(`  Folder:  ${process.cwd()}\n`)
      io.stdout(`  Version: ${AGENT_VERSION}\n\n`)

      const result = await installService(options)
      if (!result.ok) {
        io.stderr(`  ${result.message}\n`)
        return 1
      }
      io.stdout(`  ${result.message}\n\n`)
      const state = await serviceState(options)
      if (state.pairingLink) {
        io.stdout('  This computer needs pairing again:\n\n')
        io.stdout(`${indent(state.pairingLink)}\n`)
      } else {
        io.stdout('  It reuses the pairing this computer already has.\n')
        io.stdout('  If it has never been paired, run `codereach` once in this folder first.\n\n')
      }
      return 0
    }

    if (command.action === 'uninstall') {
      const result = await uninstallService(options)
      io.stdout(`\n  ${result.message}\n\n`)
      return result.ok ? 0 : 1
    }

    const state = await serviceState(options)
    if (command.action === 'status') {
      io.stdout('\n')
      io.stdout(`  Installed: ${state.installed ? 'yes' : 'no'}\n`)
      io.stdout(`  Running:   ${state.running ? 'yes' : 'no'}\n`)
      io.stdout(`  Detail:    ${state.detail}\n`)
      if (state.installed) {
        io.stdout(`  Unit:      ${state.unitPath}\n`)
        io.stdout(`  Logs:      ${state.logPath}\n`)
      }
      io.stdout('\n')
      return 0
    }

    if (command.action === 'logs') {
      const text = await readFile(state.logPath, 'utf8').catch(() => '')
      if (text.length === 0) {
        io.stdout('  The service has not written anything to stderr.\n')
        return 0
      }
      io.stdout(`${tail(text, 40)}\n`)
      return 0
    }

    // `pair`: show the note the service left when its link expired.
    const note = state.pairingLink ?? (await readPairingLink(home))
    if (!note) {
      io.stdout('\n  This computer has a working pairing. Nothing to do.\n\n')
      return 0
    }
    io.stdout(`\n${indent(note)}\n`)
    return 0
  } catch (error) {
    io.stderr(`  ${messageOf(error)}\n`)
    return 1
  }
}

