// ---------------------------------------------------------------------------
// IO
// ---------------------------------------------------------------------------

export interface Io {
  stdout: (text: string) => void
  stderr: (text: string) => void
  confirm: (question: string) => Promise<boolean>
  /** Pick one of a few options by number. Null when there is nobody to ask. */
  choose?: (question: string, options: readonly string[], defaultIndex?: number) => Promise<number | null>
  /** Read a line of text, or null if nothing is typed within `timeoutMs`. Used for the pairing code. */
  promptTimed?: (question: string, timeoutMs: number) => Promise<PromptAnswer>
  /** True when stdout is a terminal a person is reading. The pairing QR and link are printed only then. */
  stdoutIsTty?: boolean
  /** Environment for `CODEREACH_E2E_SHOW_PAIRING_IN_PIPE`. Defaults to `process.env`. */
  env?: NodeJS.ProcessEnv
}

export function defaultIo(): Io {
  return {
    stdout: (text: string) => process.stdout.write(text),
    stderr: (text: string) => process.stderr.write(text),
    confirm: async (question: string) => {
      const answer = (await askLine(question))?.trim().toLowerCase()
      return answer === 'y' || answer === 'yes'
    },
    choose: (question, options, defaultIndex = 0) => askChoice(question, options, defaultIndex),
    promptTimed: (question: string, timeoutMs: number) => askLine(question, timeoutMs),
    stdoutIsTty: process.stdout.isTTY === true,
  }
}

/**
 * Read a yes/no answer from stdin.
 *
 * Non-TTY input (a pipe, a CI run) is treated as a decline rather than a
 * hang. `codereach` must never sit forever waiting on a terminal that will
 * never answer.
 */
async function askLine(question: string, timeoutMs?: number): Promise<PromptAnswer> {
  if (!process.stdin.isTTY) {
    process.stderr.write(`\n  ${question}\n  (no terminal attached; --e2e-auto-accept pairs without typing the code)\n`)
    return ''
  }
  // Anything typed ahead (or pasted) before the question appeared is not an answer to it.
  await discardTypedAhead()

  return new Promise((resolve) => {
    process.stdout.write(`  ${question} `)
    process.stdin.setEncoding('utf8')
    process.stdin.resume()

    let timer: NodeJS.Timeout | undefined
    const finish = (answer: PromptAnswer) => {
      if (timer) clearTimeout(timer)
      process.stdin.pause()
      process.stdin.removeListener('data', onData)
      process.stdout.write('\n')
      resolve(answer)
    }
    const onData = (chunk: string) => finish(chunk.trim())

    process.stdin.on('data', onData)
    if (timeoutMs !== undefined) timer = setTimeout(() => finish(null), timeoutMs)
  })
}

/**
 * Pick one of a few numbered options.
 *
 * Non-TTY input is refused rather than guessed: a script that reaches this
 * prompt has not been told which language to install, and silently picking one
 * downloads half a gigabyte the caller did not ask for. A timeout picks the
 * default, because the default is the safe one.
 */
async function askChoice(
  question: string,
  options: readonly string[],
  defaultIndex = 0,
  timeoutMs = 5 * 60_000,
): Promise<number | null> {
  if (!process.stdin.isTTY) {
    process.stderr.write(
      `\n  ${question}\n  (no terminal attached; pass --language en or --language multi)\n`,
    )
    return null
  }
  await discardTypedAhead()

  process.stdout.write(`\n  ${question}\n`)
  options.forEach((option, index) => {
    const marker = index === defaultIndex ? ' (default)' : ''
    process.stdout.write(`    ${index + 1}. ${option}${marker}\n`)
  })

  return new Promise((resolve) => {
    process.stdout.write(`  Choose 1-${options.length}: `)
    process.stdin.setEncoding('utf8')
    process.stdin.resume()

    const onData = (chunk: string) => finish(chunk)
    function finish(raw: string | null) {
      clearTimeout(timer)
      process.stdin.pause()
      process.stdin.removeListener('data', onData)
      process.stdout.write('\n')
      if (raw === null) {
        // A timeout is not a choice: setting up voice downloads hundreds of
        // megabytes, and doing that because someone walked away is wrong.
        resolve(null)
        return
      }
      const answer = raw.trim()
      if (answer === '') {
        resolve(defaultIndex)
        return
      }
      const picked = Number(answer)
      resolve(
        Number.isInteger(picked) && picked >= 1 && picked <= options.length ? picked - 1 : null,
      )
    }
    process.stdin.on('data', onData)
    const timer = setTimeout(() => finish(null), timeoutMs)
  })
}

function discardTypedAhead(): Promise<void> {
  return new Promise((resolve) => {
    const swallow = () => undefined
    process.stdin.on('data', swallow)
    process.stdin.resume()
    setTimeout(() => {
      process.stdin.removeListener('data', swallow)
      process.stdin.pause()
      resolve()
    }, 100)
  })
}

/**
 * Block until the user interrupts.
 *
 * `SIGINT` and `SIGTERM` both resolve rather than calling `process.exit`, so
 * the `finally` block in `run` gets to shut the OpenCode server down cleanly.
 * Exiting straight from a signal handler would leave an orphaned `opencode
 * serve` holding a port.
 */
function waitForShutdown(logger: ReturnType<typeof createLogger>): Promise<void> {
  return new Promise((resolve) => {
    const stop = (signal: string) => {
      logger.info('shutdown_signal', { signal })
      // Remove both handlers (the same function objects that were added), so a
      // second Ctrl+C during a slow teardown gets Node's default and exits.
      process.off('SIGINT', onSigint)
      process.off('SIGTERM', onSigterm)
      resolve()
    }
    const onSigint = () => stop('SIGINT')
    const onSigterm = () => stop('SIGTERM')
    process.on('SIGINT', onSigint)
    process.on('SIGTERM', onSigterm)
  })
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Parse `provider/model` into the reference OpenCode expects.
 *
 * Provider ids never contain a slash; model ids often do (`openrouter/cohere/
 * north-mini-code:free`), so the split is on the *first* slash only.
 */
export function parseModelRef(raw: string): { providerID: string; id: string } {
  const trimmed = raw.trim()
  const slash = trimmed.indexOf('/')
  if (slash <= 0 || slash === trimmed.length - 1) {
    throw new Error(
      `--model must look like <provider>/<model>, for example ` +
        `opencode/deepseek-v4.1-flash-free (got "${raw}")`,
    )
  }
  return { providerID: trimmed.slice(0, slash), id: trimmed.slice(slash + 1) }
}

/** Normalise and validate the relay URL the agent was pointed at. */
export function normalizeRelayUrl(raw: string): string {
  let url: URL
  try {
    url = new URL(raw)
  } catch {
    throw new Error(`--relay must be a URL, for example ${DEFAULT_RELAY_URL} (got "${raw}")`)
  }
  if (url.protocol !== 'http:' && url.protocol !== 'https:') {
    throw new Error(`--relay must be http or https (got "${url.protocol}")`)
  }
  return url.origin
}

import { run } from './cli'

/**
 * Executable entry point.
 *
 * Kept separate from `cli.ts` so the CLI logic stays importable and testable:
 * `run(argv, io)` can be driven with a fake IO in tests, while this file is the
 * only place that touches the real `process`.
 */
const exitCode = await run(process.argv)
process.exitCode = exitCode

// The agent holds an open WebSocket and a child process. Neither keeps the
// event loop alive on its own once the socket is stopped, but if something does
// linger, exit explicitly rather than leaving a terminal that looks hung.
process.exit(exitCode)
